-- 0078_translate_content_pa.sql
-- Фаза 28: перевод контента программ — панджаби (pa).
-- Переведено вручную с русского оригинала (с опорой на вычитанный
-- английский), с терминологией, принятой в залах этой страны. Английские
-- названия упражнений (Hip Thrust, Mountain Climbers…) оставлены как есть.
-- Применять после 0072. Сопоставление — по точному русскому тексту.
-- Безопасно выполнять повторно.

update public.workout_programs p
set title_pa = v.title, description_pa = v.description
from (values
  ('pohudenie-zhenshchiny-doma', 'ਭਾਰ ਘਟਾਉਣਾ · ਔਰਤਾਂ · ਘਰ', 'ਔਰਤਾਂ ਲਈ ਭਾਰ ਘਟਾਉਣ ਦਾ ਪ੍ਰੋਗਰਾਮ (ਘਰ ਵਿੱਚ) — DonatelleX, ਇੱਕ ਸਾਲ ਦਾ ਪ੍ਰੋਗਰਾਮ। ਸਾਮਾਨ: ਡੰਬਲ, ਵੱਖ-ਵੱਖ ਟੈਂਸ਼ਨ ਵਾਲੇ ਰੈਜ਼ਿਸਟੈਂਸ ਬੈਂਡ, ਮੈਟ, ਮਜ਼ਬੂਤ ਪਲੇਟਫ਼ਾਰਮ/ਸਟੈੱਪ (ਜੇ ਹੋ ਸਕੇ)'),
  ('pohudenie-zhenshchiny-zal', 'ਭਾਰ ਘਟਾਉਣਾ · ਔਰਤਾਂ · ਜਿੰਮ', 'ਔਰਤਾਂ ਲਈ ਭਾਰ ਘਟਾਉਣ ਦਾ ਪ੍ਰੋਗਰਾਮ (ਜਿੰਮ ਵਿੱਚ) — ਇੱਕ ਸਾਲ ਦਾ ਪ੍ਰੋਗਰਾਮ। ਸਾਮਾਨ: ਟ੍ਰੈੱਡਮਿੱਲ, ਐਲਿਪਟੀਕਲ/ਸਕੀ-ਅਰਗ, ਮਸ਼ੀਨਾਂ, ਡੰਬਲ, ਕੇਬਲ, ਮੈਟ'),
  ('nabor-massy-zhenshchiny-doma', 'ਮਸਲ ਗੇਨ · ਔਰਤਾਂ · ਘਰ', 'ਔਰਤਾਂ ਲਈ ਮਸਲ ਗੇਨ ਪ੍ਰੋਗਰਾਮ (ਘਰ ਵਿੱਚ) — ਇੱਕ ਸਾਲ ਦਾ ਪ੍ਰੋਗਰਾਮ। ਸਾਮਾਨ: ਡੰਬਲ, ਵੱਖ-ਵੱਖ ਟੈਂਸ਼ਨ ਵਾਲੇ ਰੈਜ਼ਿਸਟੈਂਸ ਬੈਂਡ, ਮੈਟ, ਮਜ਼ਬੂਤ ਪਲੇਟਫ਼ਾਰਮ/ਸਟੈੱਪ'),
  ('nabor-massy-zhenshchiny-zal', 'ਮਸਲ ਗੇਨ · ਔਰਤਾਂ · ਜਿੰਮ', 'ਔਰਤਾਂ ਲਈ ਮਸਲ ਗੇਨ ਪ੍ਰੋਗਰਾਮ (ਜਿੰਮ ਵਿੱਚ) — ਇੱਕ ਸਾਲ ਦਾ ਪ੍ਰੋਗਰਾਮ «12 LEVELS»। ਸਾਮਾਨ: ਬਾਰਬੈੱਲ, ਡੰਬਲ, ਮਸ਼ੀਨਾਂ (Hip Thrust, Hack Squat, Leg Press, ਕੇਬਲ), ਰੈਜ਼ਿਸਟੈਂਸ ਬੈਂਡ, ਕੈਟਲਬੈੱਲ, TRX, ਮੈਡੀਸਨ ਬਾਲ'),
  ('pohudenie-muzhchiny-doma', 'ਭਾਰ ਘਟਾਉਣਾ · ਮਰਦ · ਘਰ', 'ਮਰਦਾਂ ਲਈ ਭਾਰ ਘਟਾਉਣ ਦਾ ਪ੍ਰੋਗਰਾਮ (ਘਰ ਵਿੱਚ) — ਇੱਕ ਸਾਲ ਦਾ ਪ੍ਰੋਗਰਾਮ। ਸਾਮਾਨ: ਡੰਬਲ, ਰੈਜ਼ਿਸਟੈਂਸ ਬੈਂਡ, ਪੁੱਲ-ਅੱਪ ਬਾਰ (ਜੇ ਹੋ ਸਕੇ), ਕੁਰਸੀ/ਬੈਂਚ, ਮੈਟ'),
  ('pohudenie-muzhchiny-zal', 'ਭਾਰ ਘਟਾਉਣਾ · ਮਰਦ · ਜਿੰਮ', 'ਮਰਦਾਂ ਲਈ ਭਾਰ ਘਟਾਉਣ ਦਾ ਪ੍ਰੋਗਰਾਮ (ਜਿੰਮ ਵਿੱਚ) — ਇੱਕ ਸਾਲ ਦਾ ਪ੍ਰੋਗਰਾਮ। ਸਾਮਾਨ: ਬਾਰਬੈੱਲ, ਡੰਬਲ, ਮਸ਼ੀਨਾਂ, ਕੇਬਲ, Battle Rope, SkiErg/ਰੋਇੰਗ ਮਸ਼ੀਨ, ਕਾਰਡੀਓ ਜ਼ੋਨ (ਟ੍ਰੈੱਡਮਿੱਲ/ਐਲਿਪਟੀਕਲ/ਸਟੇਸ਼ਨਰੀ ਬਾਈਕ)'),
  ('nabor-massy-muzhchiny-doma', 'ਮਸਲ ਗੇਨ · ਮਰਦ · ਘਰ', 'ਮਰਦਾਂ ਲਈ ਮਸਲ ਗੇਨ ਪ੍ਰੋਗਰਾਮ (ਘਰ ਵਿੱਚ) — ਇੱਕ ਸਾਲ ਦਾ ਪ੍ਰੋਗਰਾਮ। ਸਾਮਾਨ: ਡੰਬਲ, ਰੈਜ਼ਿਸਟੈਂਸ ਬੈਂਡ, ਪੁੱਲ-ਅੱਪ ਬਾਰ (ਜੇ ਹੋ ਸਕੇ), ਕੁਰਸੀ/ਬੈਂਚ, ਮੈਟ'),
  ('nabor-massy-muzhchiny-zal', 'ਮਸਲ ਗੇਨ · ਮਰਦ · ਜਿੰਮ', 'ਮਰਦਾਂ ਲਈ ਮਸਲ ਗੇਨ ਪ੍ਰੋਗਰਾਮ (ਜਿੰਮ ਵਿੱਚ) — ਇੱਕ ਸਾਲ ਦਾ ਪ੍ਰੋਗਰਾਮ। ਸਾਮਾਨ: ਪੂਰਾ ਜਿੰਮ: ਬਾਰਬੈੱਲ, ਡੰਬਲ, ਮਸ਼ੀਨਾਂ, ਪੁੱਲ-ਅੱਪ ਬਾਰ, ਰੱਸੇ, TRX, ਕੈਟਲਬੈੱਲ'),
  ('nabor-massy-nachinayushchim', 'ਸ਼ੁਰੂਆਤ ਕਰਨ ਵਾਲਿਆਂ ਲਈ ਮਸਲ ਗੇਨ', 'ਉਹਨਾਂ ਮਰਦਾਂ ਲਈ ਪਹਿਲਾ ਪ੍ਰੋਗਰਾਮ ਜੋ ਜਿੰਮ ਵਿੱਚ ਮਸਲ ਬਣਾਉਣਾ ਸ਼ੁਰੂ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹਨ। 7 ਦਿਨਾਂ ਦਾ ਸਾਈਕਲ: ਵੱਖ-ਵੱਖ ਮਸਲ ਗਰੁੱਪਾਂ ਲਈ 4 ਸਟ੍ਰੈਂਥ ਵਰਕਆਊਟ ਅਤੇ ਐਬਸ ਨਾਲ 3 ਦਿਨ ਹਲਕਾ ਕਾਰਡੀਓ। ਸ਼ੁਰੂਆਤ ਕਰਨ ਵਾਲਿਆਂ ਲਈ ਢੁਕਵਾਂ — ਕੋਈ ਔਖੀ ਤਕਨੀਕ ਨਹੀਂ, ਧਿਆਨ ਵਾਲੀਅਮ ਅਤੇ ਸਹੀ ਫ਼ਾਰਮ ''ਤੇ।')
) as v(slug, title, description)
where p.slug = v.slug;

